//! Unified dependencies for the generated project.
//!
//! The list of dependencies required by a project generated by CrawRAD is
//! centralized here, serving both the creation of new projects
//! (`criacao.rs`) and test gates and build validation.
//!
//! # Development bridge
//!
//! While `crawrad-runtime` and `crawrad-binding` are not published on crates.io,
//! they are added via local path (`--path`) to the local IDE / workspace
//! installation.

use crate::AlvoGerador;
use crawrad_note::note;
use std::path::{Component, Path, PathBuf};

#[note("dependencies-dependencia")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Dependencia {
    /// Dependency published to a registry (e.g. `makepad-widgets@1.0`).
    Registro { nome: String, versao: String },
    /// Local dependency by disk path (`--path <dir>`), with the
    /// crate features the form needs turned on (`--features a,b`).
    Caminho {
        nome: String,
        path: PathBuf,
        features: Vec<String>,
    },
}

impl Dependencia {
    pub fn registro(nome: impl Into<String>, versao: impl Into<String>) -> Self {
        Self::Registro {
            nome: nome.into(),
            versao: versao.into(),
        }
    }

    pub fn caminho(nome: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::Caminho {
            nome: nome.into(),
            path: path.into(),
            features: Vec::new(),
        }
    }

    #[note("dependencies-dependencia-with-features")]
    #[must_use]
    pub fn with_features(mut self, wanted: &[&str]) -> Self {
        if let Self::Caminho { features, .. } = &mut self {
            features.extend(wanted.iter().map(|f| (*f).to_string()));
        }
        self
    }

    pub fn nome(&self) -> &str {
        match self {
            Self::Registro { nome, .. } => nome,
            Self::Caminho { nome, .. } => nome,
        }
    }

    #[note("dependencies-dependencia-args-cargo-add")]
    pub fn args_cargo_add(&self) -> Vec<String> {
        match self {
            Self::Registro { nome, versao } => vec![format!("{nome}@{versao}")],
            Self::Caminho { path, features, .. } => {
                let mut args = vec!["--path".into(), path.display().to_string()];
                if !features.is_empty() {
                    args.push("--features".into());
                    args.push(features.join(","));
                }
                args
            }
        }
    }
}

#[note("dependencies-caminho-local-crate")]
pub fn caminho_local_crate(nome: &str) -> PathBuf {
    // 1. Override environment variable
    if let Ok(dir) = std::env::var("CRAWRAD_CRATES_DIR") {
        let p = PathBuf::from(dir).join(nome);
        if p.exists() {
            return p;
        }
    }

    // 2. An installed IDE: the install folder mirrors the repo root, so the
    //    crates sit in `crates/` beside the executable.
    if let Some(p) = std::env::current_exe()
        .ok()
        .and_then(|exe| exe.parent().map(|dir| dir.join("crates").join(nome)))
        .filter(|p| p.join("Cargo.toml").is_file())
    {
        return p;
    }

    // 3. Relative to this crate's manifest (`crates/crawrad-codegen/..`)
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    if let Some(parent) = manifest_dir.parent() {
        let candidate = parent.join(nome);
        if candidate.exists() {
            return candidate;
        }
    }

    // 4. Search upward in the tree starting from the current directory
    if let Ok(mut cur) = std::env::current_dir() {
        for _ in 0..6 {
            let candidate = cur.join("crates").join(nome);
            if candidate.exists() {
                return candidate;
            }
            if !cur.pop() {
                break;
            }
        }
    }

    // Default relative fallback
    manifest_dir.join("..").join(nome)
}

#[note("dependencies-documento-tem-bindings")]
pub fn documento_tem_bindings(doc: &crawrad_ir::Document) -> bool {
    doc.nodes.values().any(|n| !n.bindings.is_empty())
}

#[note("dependencies-dependencias-do-projeto")]
pub fn dependencias_do_projeto(
    alvo: AlvoGerador,
    com_formulario: bool,
    usa_binding: bool,
) -> Vec<Dependencia> {
    let mut deps = Vec::new();

    match alvo {
        AlvoGerador::Makepad => {
            if com_formulario {
                // Main toolkit
                deps.push(Dependencia::registro("makepad-widgets", "1.0"));
                // The generated code emits `use crawrad_runtime::prelude::*;`
                deps.push(Dependencia::caminho(
                    "crawrad-runtime",
                    caminho_local_crate("crawrad-runtime"),
                ));
                // The generated code emits calls to the native Makepad adapter (`crawrad_runtime_makepad::...`)
                deps.push(Dependencia::caminho(
                    "crawrad-runtime-makepad",
                    caminho_local_crate("crawrad-runtime-makepad"),
                ));
            }
        }
        AlvoGerador::Egui => {
            if com_formulario {
                // Main toolkit
                deps.push(Dependencia::registro("eframe", "0.36"));
                // the generated code calls `crawrad_runtime::...` (the file dialogs)
                deps.push(Dependencia::caminho(
                    "crawrad-runtime",
                    caminho_local_crate("crawrad-runtime"),
                ));
            }
        }
        AlvoGerador::Slint => {
            if com_formulario {
                // Main toolkit
                deps.push(Dependencia::registro("slint", "1.9"));
                deps.push(Dependencia::caminho(
                    "crawrad-runtime",
                    caminho_local_crate("crawrad-runtime"),
                ));
                deps.push(Dependencia::caminho(
                    "crawrad-runtime-slint",
                    caminho_local_crate("crawrad-runtime-slint"),
                ));
            }
        }
    }

    // Forms with data binding require the `crawrad-binding` core
    if usa_binding {
        deps.push(Dependencia::caminho(
            "crawrad-binding",
            caminho_local_crate("crawrad-binding"),
        ));
    }

    deps
}

#[note("dependencies-minimum-rustc")]
pub fn minimum_rustc(target: AlvoGerador, with_form: bool) -> (u32, u32) {
    match (target, with_form) {
        // Edition 2024 itself: no dependency of ours is added without a form.
        (_, false) => (1, 85),
        (AlvoGerador::Makepad, true) => (1, 88),
        (AlvoGerador::Egui, true) => (1, 95),
        (AlvoGerador::Slint, true) => (1, 88),
    }
}

#[note("dependencies-component-crate-path")]
fn component_crate_path(name: &str) -> PathBuf {
    caminho_local_crate(&format!("../components/{name}"))
}

#[note("dependencies-has-bound-grid")]
pub fn has_bound_grid(doc: &crawrad_ir::Document) -> bool {
    doc.nodes.values().any(|n| {
        n.class == "Grid"
            && matches!(n.props.get("data_source"), Some(crawrad_ir::Value::Ref(id)) if !id.is_empty())
    })
}

#[note("dependencies-has-bound-controls")]
pub fn has_bound_controls(doc: &crawrad_ir::Document) -> bool {
    let nodes: Vec<&crawrad_ir::Node> = doc.nodes.values().collect();
    let has_controls = crate::targets::data_binding::collect_bound_controls(doc, &nodes)
        .is_ok_and(|controls| !controls.is_empty());
    let has_actions = crate::targets::data_binding::collect_dataset_actions(doc, &nodes)
        .is_ok_and(|actions| !actions.is_empty());
    has_controls || has_actions
}

#[note("dependencies-component-dependencies")]
pub fn component_dependencies(doc: &crawrad_ir::Document, alvo: AlvoGerador) -> Vec<Dependencia> {
    let mut deps = Vec::new();
    // Every generated egui `main` reports a startup failure through
    // `crawrad_runtime`. A project created before 21/10/2026 has
    // no `crawrad-runtime` in its manifest, and its next Generate would not
    // compile; `cargo add` of a crate already there rewrites the same line.
    if alvo == AlvoGerador::Egui {
        deps.push(Dependencia::caminho(
            "crawrad-runtime",
            caminho_local_crate("crawrad-runtime"),
        ));
    }
    // an Edit or a CheckBox bound to a `Dataset` opens it through
    // `crawrad_binding::PortaDbBridge`, on the SQLite driver -- the beta scope,
    // the same one the bound grid opens. The driver is a FEATURE of the
    // `portadb` the binding crate links, so it is asked here: the engines'
    // own `requires` (crate + features) are not applied to the project yet.
    let bound = has_bound_controls(doc);
    if bound {
        deps.push(
            Dependencia::caminho("crawrad-binding", caminho_local_crate("crawrad-binding"))
                .with_features(&["rusqlite"]),
        );
    }
    if has_bound_grid(doc) {
        deps.push(Dependencia::caminho(
            "datagrid",
            component_crate_path("datagrid"),
        ));
        deps.push(Dependencia::caminho(
            "datagrid-sql",
            component_crate_path("datagrid-sql"),
        ));
        if alvo == AlvoGerador::Egui {
            deps.push(Dependencia::caminho(
                "crawrad-runtime-egui",
                caminho_local_crate("crawrad-runtime-egui"),
            ));
        }
    }
    deps
}

#[note("dependencies-gerar-cargo-toml")]
pub fn gerar_cargo_toml(
    nome: &str,
    alvo: AlvoGerador,
    com_formulario: bool,
    usa_binding: bool,
    extras: &[Dependencia],
) -> String {
    let mut deps = dependencias_do_projeto(alvo, com_formulario, usa_binding);
    deps.extend_from_slice(extras);
    cargo_toml_from(nome, alvo, com_formulario, &deps)
}

fn cargo_toml_from(
    name: &str,
    target: AlvoGerador,
    with_form: bool,
    deps: &[Dependencia],
) -> String {
    let (major, minor) = minimum_rustc(target, with_form);
    let mut toml = format!(
        "[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2024\"\nrust-version = \"{major}.{minor}\"\n\n[dependencies]\n"
    );
    for dep in deps {
        match dep {
            Dependencia::Registro { nome, versao } => {
                toml.push_str(&format!("{nome} = \"{versao}\"\n"));
            }
            Dependencia::Caminho {
                nome,
                path,
                features,
            } => {
                let p = path.display().to_string().replace('\\', "/");
                if features.is_empty() {
                    toml.push_str(&format!("{nome} = {{ path = \"{p}\" }}\n"));
                } else {
                    let list = features
                        .iter()
                        .map(|f| format!("\"{f}\""))
                        .collect::<Vec<_>>()
                        .join(", ");
                    toml.push_str(&format!(
                        "{nome} = {{ path = \"{p}\", features = [{list}] }}\n"
                    ));
                }
            }
        }
    }
    toml
}

/// The `[patch.crates-io]` that builds a Makepad app against the IDE's own
/// `makepad-platform` (`vendor/`), as the IDE does: its window takes the `.exe`'s
/// icon (resource 1, the project's `icon.ico`), and it keeps the Alt+Enter fix and
/// the shader cache. Cargo honours it only in the WORKSPACE root's manifest. Empty
/// when the vendored copy is not found beside the crates.
pub fn patch_makepad_platform() -> String {
    match vendored_platform() {
        Some(v) => {
            let p = v.display().to_string().replace('\\', "/");
            format!("\n[patch.crates-io]\nmakepad-platform = {{ path = \"{p}\" }}\n")
        }
        None => String::new(),
    }
}

/// `gerar_cargo_toml` for a manifest that will live in `manifest_dir`: every
/// path dependency is written relative to that folder (see [`manifest_path`]),
/// so the project does not pin one checkout on one machine.
#[note("dependencies-cargo-toml-at")]
pub fn cargo_toml_at(
    manifest_dir: &Path,
    nome: &str,
    alvo: AlvoGerador,
    com_formulario: bool,
    usa_binding: bool,
    extras: &[Dependencia],
) -> String {
    let mut deps = dependencias_do_projeto(alvo, com_formulario, usa_binding);
    deps.extend_from_slice(extras);
    let deps: Vec<Dependencia> = deps
        .into_iter()
        .map(|d| match d {
            Dependencia::Caminho {
                nome,
                path,
                features,
            } => Dependencia::Caminho {
                nome,
                path: manifest_path(manifest_dir, &path),
                features,
            },
            other => other,
        })
        .collect();
    // The project's own deps are already in `deps`: no second framework list.
    cargo_toml_from(nome, alvo, com_formulario, &deps)
}

/// `patch_makepad_platform` for the workspace manifest in `manifest_dir`, with
/// the vendored path relative to it (see [`manifest_path`]).
#[note("dependencies-patch-makepad-platform-at")]
pub fn patch_makepad_platform_at(manifest_dir: &Path) -> String {
    match vendored_platform() {
        Some(v) => {
            let p = manifest_path(manifest_dir, &v)
                .display()
                .to_string()
                .replace('\\', "/");
            format!("\n[patch.crates-io]\nmakepad-platform = {{ path = \"{p}\" }}\n")
        }
        None => String::new(),
    }
}

fn vendored_platform() -> Option<PathBuf> {
    caminho_local_crate("crawrad-runtime-makepad")
        .parent()
        .and_then(|crates| crates.parent())
        .map(|root| root.join("vendor").join("makepad-platform"))
        .filter(|v| v.join("Cargo.toml").is_file())
}

/// The path a manifest in `manifest_dir` should write to reach `target`.
///
/// Relative whenever one exists — inside the checkout (`examples/`) and in a
/// sibling folder on the same drive alike — so the project keeps building
/// when the whole tree moves together. **Absolute only across drives (or
/// Windows path prefixes)**: there no relative path exists at all, and an
/// absolute one is still a working build on this machine. The runtime crates
/// are not on crates.io yet (`publish = false`), so a path is the only option.
#[note("dependencies-manifest-path")]
pub fn manifest_path(manifest_dir: &Path, target: &Path) -> PathBuf {
    let from = normalize(&absolute(manifest_dir));
    let to = normalize(&absolute(target));
    relative_path(&from, &to).unwrap_or(to)
}

fn absolute(p: &Path) -> PathBuf {
    std::path::absolute(p).unwrap_or_else(|_| p.to_path_buf())
}

/// Folds `.` and `..` lexically (no disk access: the project folder may not
/// exist yet, and `canonicalize` adds a verbatim prefix on Windows).
fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                if !out.pop() {
                    out.push("..");
                }
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

fn same_component(a: Component<'_>, b: Component<'_>) -> bool {
    if cfg!(windows) {
        a.as_os_str()
            .to_string_lossy()
            .eq_ignore_ascii_case(&b.as_os_str().to_string_lossy())
    } else {
        a == b
    }
}

/// `to` relative to `from`, both absolute and normalized; `None` when they do
/// not share a root (another drive).
fn relative_path(from: &Path, to: &Path) -> Option<PathBuf> {
    let f: Vec<Component<'_>> = from.components().collect();
    let t: Vec<Component<'_>> = to.components().collect();
    let rooted = |c: &Component<'_>| matches!(c, Component::Prefix(_) | Component::RootDir);
    let common = f
        .iter()
        .zip(&t)
        .take_while(|(a, b)| same_component(**a, **b))
        .count();
    // The roots differ (`C:` vs `D:`): no relative path exists.
    if f.iter().take_while(|c| rooted(c)).count() > common {
        return None;
    }
    let mut out = PathBuf::new();
    for _ in common..f.len() {
        out.push("..");
    }
    for c in &t[common..] {
        out.push(c.as_os_str());
    }
    if out.as_os_str().is_empty() {
        out.push(".");
    }
    Some(out)
}

/// The dependencies a project needs when it ships translated locales.
pub fn locale_dependencies() -> Vec<Dependencia> {
    vec![Dependencia::registro("sys-locale", "0.3")]
}

